    body { overflow: hidden; }
    #map { height: 100vh; width: 100%; }
    .sidebar { height: 100vh; overflow-y: auto; border-left: 1px solid #ddd; background: #f8f9fa; }
    .legend-box { height: 12px; width: 30px; display: inline-block; margin-right: 8px; }
    @media (max-width: 768px) { .sidebar { height: auto; border-left: none; border-top: 1px solid #ddd; } }
    .leaflet-popup-content-wrapper,.leaflet-popup-content { border-radius: 0 !important; }
	.grayscale-map { filter: grayscale(100%) brightness(103%) contrast(100%); }
