	.val-row { min-height: 1.0em; min-width: 25px; display: flex; padding: 1px; align-items: center; justify-content: center; }
	canvas { background: white; }

	.custom-modal-overlay { display: flex; position: fixed; z-index: 9999; left: 0; top: 0; width: 100%; height: 100%; background-color: rgba(0,0,0,0.5); align-items: center; justify-content: center; }
	.custom-modal-content { background-color: #fff; padding: 30px; border-radius: 8px; width: 90%; max-width: 800px; position: relative; box-shadow: 0 4px 15px rgba(0,0,0,0.3); }
	.close-button {	position: absolute; right: 15px; top: 15px; }
