<script>
// ================= RD PROJECTIE =================
const crsRD = new L.Proj.CRS(
    "EPSG:28992", "+proj=sterea +lat_0=52.15616055555555 +lon_0=5.38763888888889 +k=0.9999079 +x_0=155000 +y_0=463000 +ellps=bessel +towgs84=565.417,50.3319,465.552,-0.398957,0.343988,-1.8774,4.0725 +units=m +no_defs",
    { origin: [-285401.92, 903401.92], resolutions: [3440.64,1720.32,860.16,430.08,215.04, 107.52,53.76,26.88,13.44,6.72, 3.36,1.68,0.84,0.42,0.21]}
);

// ================= KAART =================
const map = L.map('map', { crs: crsRD, continuousWorld: true, zoomControl: false });

// ============= PDOK ACHTERGROND =============
L.tileLayer(
    "https://service.pdok.nl/brt/achtergrondkaart/wmts/v2_0/grijs/EPSG:28992/{z}/{x}/{y}.png",
	//"https://service.pdok.nl/hwh/luchtfotorgb/wmts/v1_0/Actueel_ortho25/EPSG:28992/{z}/{x}/{y}.jpeg",
    {
        minZoom: 0,
        maxZoom: 14,
        tileSize: 256,
        attribution: "© PDOK",
        continuousWorld: true,
		className: 'grayscale-map'
    }
).addTo(map);

// ================ TrafficData ===============
const d = trafficData; 

// ================= PROJECTDATA =================
const variants = (d.meta?.maps?.vars) || [];
const types = (d.meta?.maps?.types) || [];
const boundary = (d.boundary?.geometry?.coordinates) || [];
const features = (d.geo?.features) || [];
const vristats = (d.vristats) || [];
const krstats = (d.krstats) || [];
const krint = (d.krint) || [];
const haltes = (d.haltes) || [];
const stappers = (d.stappers) || [];

// ================= METADATA =================
document.getElementById('projectTitle').innerHTML = `<h3><strong>Project:</strong> ${d.meta.prj} - ${d.meta.nam}</h3>`;
document.getElementById('vmaVersie').innerHTML = `<strong>VMA-versie:</strong> ${d.meta.vma}`;
document.getElementById('exportDatum').innerHTML = `<strong>Projectversie:</strong>  ${d.meta.dat}`;
document.title = `Project: ${d.meta.prj} - ${d.meta.nam}`;

// ================= BOUNDARY =================
const boundarydraw = L.polyline(boundary.map(pt => crsRD.unproject(L.point(pt[0], pt[1]))), { color: 'black', weight: 4, zindex: 0 }).addTo(map);
map.fitBounds(boundarydraw.getBounds());

let minX = Math.min(...boundary.map(p => p[0]));
let maxX = Math.max(...boundary.map(p => p[0]));
let minY = Math.min(...boundary.map(p => p[1]));
let maxY = Math.max(...boundary.map(p => p[1]));

// ================= INTENSITEITEN =================
const intensiteitenLookup = {};
d.stats.forEach(([vIdx, tIdx, linknr, dir, value]) => {
    const vName = variants[vIdx];
    const tName = types[tIdx];
    if (!intensiteitenLookup[vName]) intensiteitenLookup[vName] = {};
    if (!intensiteitenLookup[vName][tName]) intensiteitenLookup[vName][tName] = {};
    if (!intensiteitenLookup[vName][tName][linknr]) intensiteitenLookup[vName][tName][linknr] = {};
    
    intensiteitenLookup[vName][tName][linknr][dir] = value;
});

// ================= UI =================
variants.forEach(v=>{
    let o = document.createElement("option");
    o.value = v;
    o.text = v;
    variantSelect.appendChild(o);
});

// ====== Kruispunt overlay ============

function showKruispuntInfo(varideen, krideen, typeeen, varidtwee) {
    const win = document.getElementById('infoWindow');
    const content = document.getElementById('infoContent');
    const title = document.getElementById('infoTitle');

	// Helper functie voor de tekstuele beoordeling
    const getBeoordelingTekst = (waarde) => {
        if (waarde === 0) return "Voldoet";
        if (waarde === 1) return "Potentieel aandachtspunt";
        if (waarde === 2) return "Reeel aandachtspunt";
        return "Onbekend";
    };

    // --- DATA VARIANT 1 ---
    const krData = krint.find(i => i[0] === varideen && i[1] === krideen);
    if (!krData) return; // Stop als er geen basisdata is

    let variant1Naam = document.getElementById('variantSelect').value;
	variant1Naam = (document.getElementById('zichtSelect').value === 'twee' && varidtwee === "") ? document.getElementById('variantSelectTwo').value : document.getElementById('variantSelect').value;
    const [ , , takkenn, hoekenn, , pos, pas, pet, vos, vas, vet] = krData;
    const takken = takkenn.map(t => String(t));
    const uniekeTakkenString = [...new Set(takken)].filter(t => t !== "Nm" && t.trim() !== "").join(' / ');
    const hoeken = hoekenn.map(t => t - 90);
    
    // VRI Data Variant 1
    const vriData = vristats.find(v => v[0] === varideen && v[1] === krideen);
    if (vriData && typeeen === 1) {
        const tag = vriData[4]; // index 4 is de tag
        variant1Naam += ` (kr${tag})`;
    }

    // --- DATA VARIANT 2 ---
    const krDatatwee = varidtwee !== "" ? krint.find(i => i[0] === varidtwee && i[1] === krideen) : null;
    let variant2Naam = "";
    let vriDatatwee = null;
    let takkentwee, hoekentwee, pettwee, vettwee, postwee, pastwee, vastwee;

    if (krDatatwee) {
        variant2Naam = document.getElementById('variantSelectTwo').value;
        const [ , , takkentw, hoekentw, , postw, pastw, pettw, , vastw, vettw] = krDatatwee;
        takkentwee = takkentw.map(t => String(t));
        hoekentwee = hoekentw.map(t => t - 90);
        pettwee = pettw; vettwee = vettw; postwee = postw; pastwee = pastw; vastwee = vastw;

        vriDatatwee = vristats.find(v => v[0] === varidtwee && v[1] === krideen);
        if (vriDatatwee && typeeen === 1) {
            const tagtwee = vriDatatwee[4];
            variant2Naam += ` (kr${tagtwee})`;
        }
    }

    // --- UI INSTELLEN ---
    title.innerText = `Kruispunt: ${uniekeTakkenString} (Gemotoriseerd verkeer)`;
    win.style.display = 'block';

    let html = `<table class="table table-sm table-striped table-borderless" style="text-align: center; vertical-align: middle;">`;

    // FUNCTIE VOOR VRI RIJ (Helper om code kort te houden)
    const getVriRow = (data) => {
        if (!data || typeeen !== 1) return `<tr><td>&nbsp;</td><td></td><td></td><td></td></tr>`;
        const [ , , , , , vOS, vAS, wOS, wAS, cOS, cAS, , , bOS, bAS] = data;
        return `<tr><td></td><td style="text-align: right; ">Maximum V/C-waarde / Gewogen V/C-waarde / Cyclustijd:</td><td>${vOS}% / ${wOS}% / ${cOS}s (${getBeoordelingTekst(bOS)})</td><td>${vAS}% / ${wAS}% / ${cAS}s (${getBeoordelingTekst(bAS)})</td></tr>`;
    };

    if (!krDatatwee) {
        // ENKELVOUDIGE WEERGAVE
        html += `<tr><th></th><th style="width: 470px;">Etmaal (0-24 uur)</th><th style="width: 470px;">Ochtendspits (7-9 uur)</th><th style="width: 470px;">Avondspits (16-18 uur)</th></tr>`;
        html += `<tr>
            <td style="writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; font-weight: bold;">${variant1Naam}</td>
            <td><canvas id="eenet" width="470" height="470"></canvas></td>
            <td><canvas id="eenos" width="470" height="470"></canvas></td>
            <td><canvas id="eenas" width="470" height="470"></canvas></td>
        </tr>`;
        html += getVriRow(vriData);
    } else {
        // VERGELIJKENDE WEERGAVE (Variant 2 boven, Variant 1 onder)
        html += getVriRow(vriDatatwee);
        html += `<tr>
            <td style="writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; font-weight: bold;">${variant2Naam}</td>
            <td><canvas id="tweeet" width="450" height="450"></canvas></td>
            <td><canvas id="tweeos" width="450" height="450"></canvas></td>
            <td><canvas id="tweeas" width="450" height="450"></canvas></td>
        </tr>`;
        html += `<tr><th></th><th style="width: 470px;">Etmaal (0-24 uur)</th><th style="width: 470px;">Ochtendspits (7-9 uur)</th><th style="width: 470px;">Avondspits (16-18 uur)</th></tr>`;
        html += `<tr>
            <td style="writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; font-weight: bold;">${variant1Naam}</td>
            <td><canvas id="eenet" width="450" height="450"></canvas></td>
            <td><canvas id="eenos" width="450" height="450"></canvas></td>
            <td><canvas id="eenas" width="450" height="450"></canvas></td>
        </tr>`;
        html += getVriRow(vriData);

    }

    html += `</table>`;
    content.innerHTML = html;

    // --- RENDEREN OP CANVAS ---
    // Variant 1 altijd renderen
    renderKruispunt({ takken: takken, hoeken: hoeken, pin: pet, vin: vet, canvasId: "eenet" });
    renderKruispunt({ takken: takken, hoeken: hoeken, pin: pos, vin: vas, canvasId: "eenos" });
    renderKruispunt({ takken: takken, hoeken: hoeken, pin: pas, vin: vas, canvasId: "eenas" });

    // Variant 2 alleen als deze bestaat
    if (krDatatwee) {
        renderKruispunt({ takken: takkentwee, hoeken: hoekentwee, pin: pettwee, vin: vettwee, canvasId: "tweeet" });
        renderKruispunt({ takken: takkentwee, hoeken: hoekentwee, pin: postwee, vin: vastwee, canvasId: "tweeos" });
        renderKruispunt({ takken: takkentwee, hoeken: hoekentwee, pin: pastwee, vin: vastwee, canvasId: "tweeas" });
    }
}

