	let colors = [[0,"#00FF00"]];
	if(types[0]==="p") { colors = [[0,"#00A03C"],[400,"#00FF00"],[1500,"yellow"],[2500,"#FF8040"],[5000,"red"],[7500,"purple"],[10000,"grey"]]; }
	if(types   ==="pet"){ colors = [[0,"#00A03C"],[4000,"#00FF00"],[15000,"yellow"],[25000,"#FF8040"],[50000,"red"],[75000,"purple"],[100000,"grey"]]; }
	if(types[0]==="o") { colors = [[0,"#00A03C"],[250,"#00FF00"],[400,"yellow"],[1000,"#FF8040"],[2000,"red"],[3000,"purple"],[4000,"grey"]]; }
	if(types   ==="oet"){ colors = [[0,"#00A03C"],[2500,"#00FF00"],[4000,"yellow"],[10000,"#FF8040"],[20000,"red"],[30000,"purple"],[40000,"grey"]]; }
	if(types[0]==="f") { colors = [[0,"#00A03C"],[0.0901,"#00FF00"],[0.1802,"yellow"],[0.4505,"#FF8040"],[0.9009,"red"],[1.3514,"purple"],[1.8018,"grey"]]; }
	if(types   ==="fet"){ colors = [[0,"#00A03C"],[0.9009,"#00FF00"],[1.8018,"yellow"],[4.5045,"#FF8040"],[9.0090,"red"],[13.5135,"purple"],[18.0180,"grey"]]; }
	return colors;
}

