function getLegend(types) {
	let legend = [];
	let levels = getColors(types);
	if(types[0] != "f") {
		for(let i=0;i<levels.length;i++){
			let from = levels[i][0];
			let to = (i<levels.length-1)?levels[i+1][0]:null;
			legend.push({color:levels[i][1], label:to?`${from}-${to}`:`${from}+`});
		}
	} else {
		for(let i=0;i<levels.length;i++){
			let from = Math.round(levels[i][0] * 555);
			let to = (i<levels.length-1)?Math.round(levels[i+1][0] * 555):null;
			legend.push({color:levels[i][1], label:to?`${from}-${to}`:`${from}+`});
		}
	}
	return legend;
}

function getKruispuntColor(type) {
    switch(type) {
        case 1: return "#CC79A7";	// Gelijkwaardig kruispunt
        case 2: return "#56B4E9";	// Voorrangskruispunt
		case 4: return "#0072B2";	// Rotonde
        default: return "gray";		// Overig
    }
}

// ================= LAYER =================
let layer = L.layerGroup().addTo(map);

// ================= OFFSET =================
function offsetLineRD(coords, offset){

  let result = [];

  for(let i = 0; i < coords.length; i++){

    let p = coords[i];

    let nx = 0;
    let ny = 0;

    // vorige segment
    if(i > 0){
      let pPrev = coords[i-1];
      let dx = p[0] - pPrev[0];
      let dy = p[1] - pPrev[1];
      let len = Math.sqrt(dx*dx + dy*dy);

      if(len > 0){
        nx += -dy / len;
        ny +=  dx / len;
      }
    }

    // volgende segment
    if(i < coords.length - 1){
      let pNext = coords[i+1];
      let dx = pNext[0] - p[0];
      let dy = pNext[1] - p[1];
      let len = Math.sqrt(dx*dx + dy*dy);

      if(len > 0){
        nx += -dy / len;
        ny +=  dx / len;
      }
    }

    let lenN = Math.sqrt(nx*nx + ny*ny);

    if(lenN === 0){
      result.push(p);
      continue;
    }

    nx /= lenN;
    ny /= lenN;

    result.push([
      p[0] + nx * offset,
      p[1] + ny * offset
    ]);
  }

  return result;
}

// ======== CENTERLINE ==================

function drawCenterLine(coords){

	if(coords.length === 0) return;

	L.polyline(boundary.map(coords => crsRD.unproject(L.point(pt[0], pt[1]))), { color: 'black', color: "black", weight: 0.3, opacity: 1 }).addTo(map);

	L.polyline(base,{
		color: "black",
		weight: 0.4,
		opacity: 1
	}).addTo(layer);
}

// ================= MAP UPDATE =================
function updateMap() {
    layer.clearLayers();

    // Haal de elementen op
    const zichtSelect = document.getElementById('zichtSelect');
    const variantSelect = document.getElementById('variantSelect');
    const variantSelectTwo = document.getElementById('variantSelectTwo');
    const typeSelect = document.getElementById('typeSelect');
    const timeSelect = document.getElementById('timeSelect');
	const kruispuntCheckbox = document.getElementById('kruispuntSelect').checked;
    const kruispuntSelectContainer = document.getElementById('kruispuntSelectContainer');
	const halteCheckbox = document.getElementById('halteSelect').checked;
    const halteSelectContainer = document.getElementById('halteSelectContainer');
	const intensiteitenCheckbox = document.getElementById('intensiteitenSelect').checked;

    const mode = zichtSelect.value;
    const var1 = variantSelect.value;
    const var2 = variantSelectTwo ? variantSelectTwo.value : null;
    
    const typeKey = typeSelect.value;
    const timeKey = timeSelect.value;
    const fullType = typeKey + timeKey;

    // Haal de bron-data op uit je lookup
    const data1 = (intensiteitenLookup[var1] && intensiteitenLookup[var1][fullType]) ? intensiteitenLookup[var1][fullType] : {};

	let data = {};
    let baseData = {}; // Nieuw: om de grijze basiswaarden op te slaan

    if (mode === 'een') {
        data = data1;
    } else {
        const data2 = (var2 && intensiteitenLookup[var2] && intensiteitenLookup[var2][fullType]) ? intensiteitenLookup[var2][fullType] : {};
        const allKeys = new Set([...Object.keys(data1), ...Object.keys(data2)]);
        
        allKeys.forEach(linkId => {
            data[linkId] = {};
            baseData[linkId] = {};
            [1, 2].forEach(dir => {
                const val1 = data1[linkId] && data1[linkId][dir] !== undefined ? data1[linkId][dir] : 0;
                const val2 = data2[linkId] && data2[linkId][dir] !== undefined ? data2[linkId][dir] : 0;
                
                baseData[linkId][dir] = val1; // De grijze basis
                data[linkId][dir] = val2 - val1; // Het verschil
            });
        });
    }

    // Update de HTML elementen in onderbalk
    document.getElementById('display-variant').innerText = (zichtSelect.value === 'twee') ? `Vergelijking van ${var2} ten opzichte van ${var1}` : var1;
    document.getElementById('display-type').innerText = typeSelect.options[typeSelect.selectedIndex].text;
    document.getElementById('display-time').innerText = timeSelect.options[timeSelect.selectedIndex].text;

    if (typeKey === 'p') {
        kruispuntSelectContainer.style.display = 'block';
    } else {
        kruispuntSelectContainer.style.display = 'none';
    }

    if (typeKey === 'ox') {
        halteSelectContainer.style.display = 'block';
    } else {
        halteSelectContainer.style.display = 'none';
    }

    let labelsDrawn = new Set(); // Houdt bij welke linkId al een label heeft

    // 1. Legenda bijwerken
    let legendDiv = document.getElementById("legendint");
    
    const legendItems = getLegend(fullType);

    if (mode === 'twee') {
		legendDiv.innerHTML = `
			<div><span class="legend-box" style="background:#A0A0A0"></span> Basis</div>
			<div><span class="legend-box" style="background:red"></span> Toename</div>
			<div><span class="legend-box" style="background:#00A03C"></span> Afname</div>
		`;
	} else if (legendItems.length > 0) {
		legendDiv.innerHTML = ``;
        legendItems.forEach(l => {
            let div = document.createElement("div");
            div.innerHTML = `<span class="legend-box" style="background:${l.color}"></span> ${l.label}`;
            legendDiv.appendChild(div);
        });
    }

	function getColor(value, currentType, status) {
		if (status === "basis") {
			return "#A0A0A0"; // Donkergrijs voor de eerste variant
		}
		
		if (status === "diff") {
			// Groen voor afname (negatief), Rood voor toename (positief)
			return value >= 0 ? "red" : "#00A03C";
		}

		// Default: normale kleuren voor 'een variant' modus
		let levels = getColors(currentType);
		let color = levels[0][1];
		for (let i = 0; i < levels.length; i++) {
			if (value >= levels[i][0]) color = levels[i][1];
		}
		return color;
	}

	// Bepaal de maximale absolute waarde van Variant 2 voor een consistente schaal
	let maxLoad = 0;
	Object.keys(data).forEach(linkId => {
		[1, 2].forEach(dir => {
			const v1 = baseData[linkId]?.[dir] || 0;
			const diff = data[linkId]?.[dir] || 0;
			const v2 = Math.abs(v1 + diff); // De totale waarde van de variant die we vergelijken
			if (v2 > maxLoad) maxLoad = v2;
			if (Math.abs(v1) > maxLoad) maxLoad = Math.abs(v1);
		});
	});
	const maxWidth = 45;

    // 4. De tekenfunctie
	function drawIntensityPolygon(linkId, coordsRD, value, directionSign, props, fullType, status, extraOffset = 0) {
		if (value === undefined || value === null || value === 0) return;

		const absoluteValue = Math.abs(value);
		let width = (absoluteValue / (maxLoad || 1)) * maxWidth;

		let innerDist, outerDist;

		if (status === "diff" && value < 0) {
			// AFNAME (Groen): Moet EXACT op de buitenrand van de grijze balk beginnen
			// Geen extra offsets toevoegen aan de buitenkant om verspringing te voorkomen
			innerDist = extraOffset * directionSign; 
			outerDist = (extraOffset - width) * directionSign;
		} else {
			// BASIS (Grijs) of TOENAME (Rood)
			// Alleen bij de absolute middellijn (extraOffset 0) gebruiken we de midlineOverlap
			let currentStart = (extraOffset === 0) ? -0.15 : extraOffset;
			innerDist = currentStart * directionSign;
			outerDist = (extraOffset + width) * directionSign;
		}

		let innerSide = offsetLineRD(coordsRD, innerDist);
		let outerSide = offsetLineRD(coordsRD, outerDist);

		let fullPolyRD = outerSide.concat(innerSide.reverse());
		
		// Wiskundige clipping (Sutherland-Hodgman principe voor een bounding box)
        let clippedPolyRD = fullPolyRD;

        const clip = (points, limit, axis, isUpper) => {
            let result = [];
            for (let i = 0; i < points.length; i++) {
                let p1 = points[i];
                let p2 = points[(i + 1) % points.length];
                let v1 = p1[axis], v2 = p2[axis];

                const inside = isUpper ? (v) => v <= limit : (v) => v >= limit;

                if (inside(v1)) {
                    if (inside(v2)) {
                        result.push(p2);
                    } else {
                        // Snijpunt berekenen
                        let t = (limit - v1) / (v2 - v1);
                        let intersect = axis === 0 
                            ? [limit, p1[1] + t * (p2[1] - p1[1])]
                            : [p1[0] + t * (p2[0] - p1[0]), limit];
                        result.push(intersect);
                    }
                } else if (inside(v2)) {
                    // Snijpunt berekenen
                    let t = (limit - v1) / (v2 - v1);
                    let intersect = axis === 0 
                        ? [limit, p1[1] + t * (p2[1] - p1[1])]
                        : [p1[0] + t * (p2[0] - p1[0]), limit];
                    result.push(intersect, p2);
                }
            }
            return result;
        };

        // Pas de snijmethode toe voor alle 4 de zijden van de bounding box
        if (clippedPolyRD.length > 0) clippedPolyRD = clip(clippedPolyRD, minX, 0, false);
        if (clippedPolyRD.length > 0) clippedPolyRD = clip(clippedPolyRD, maxX, 0, true);
        if (clippedPolyRD.length > 0) clippedPolyRD = clip(clippedPolyRD, minY, 1, false);
        if (clippedPolyRD.length > 0) clippedPolyRD = clip(clippedPolyRD, maxY, 1, true);

        let latLngs = clippedPolyRD.map(pt => crsRD.unproject(L.point(pt[0], pt[1])));

		L.polygon(latLngs, {
			fillColor: getColor(value, fullType, status),
			fillOpacity: 1,
			stroke: true,
			weight: 0.2, // Iets dikkere stroke helpt bij het "vullen" van de anti-aliasing kieren
			color: getColor(value, fullType, status),
			lineJoin: 'miter',
			interactive: false
		}).addTo(layer);

		const currentZoom = map.getZoom();

		// Teken het label één keer per wegvak
		if (currentZoom > 10 && fullType[0] != "f" && !labelsDrawn.has(linkId) && intensiteitenCheckbox) {
			
			labelsDrawn.add(linkId);
			
			// In de vergelijkingsmodus bevat 'data' de verschil-waarden (delta)
			let val1 = data[linkId]?.[1] || 0; 
			let val2 = data[linkId]?.[2] || 0; 

			// 1. Bepaal de modus en de bijbehorende drempelwaarde
			const isVergelijking = (zichtSelect && zichtSelect.value === 'twee');
			const drempel = isVergelijking ? 20 : 50;

			// 2. Check of één van de richtingen de drempel haalt en of de geometrie klopt
			if ((Math.abs(val1) >= drempel || Math.abs(val2) >= drempel) && props.x && props.y && props.a && props.l > 30) {
				
				const midPos = crsRD.unproject(L.point(props.x, props.y));
				let finalRotation = (props.a > 90 && props.a < 270) ? props.a + 180 : props.a;

				let topRowValue, bottomRowValue;
				if (props.o === 0) {
					topRowValue = 0; bottomRowValue = 0;
				} else {
					// Oriëntatie check: bepaal welke waarde boven/onder komt
					const eerste = (props.o === 2);
					topRowValue = eerste ? val1 : val2;
					bottomRowValue = eerste ? val2 : val1;                
				}

				const formatLabel = (val) => {
					if (Math.abs(val) < drempel) return "&nbsp;";
					const afgerond = Math.round(val);
					const prefix = (isVergelijking && afgerond > 0) ? "+" : "";
					return `${prefix}${afgerond}`;
				};

				const topContent = formatLabel(topRowValue);
				const bottomContent = formatLabel(bottomRowValue);

				// Alleen de marker plaatsen als er daadwerkelijk tekst is om te tonen
				if (topContent !== "&nbsp;" || bottomContent !== "&nbsp;") {
					const labelIcon = L.divIcon({
						className: 'intensity-label-container',
						html: `
							<div class="intensity-label-dual" style="transform: translate(-50%, -50%) rotate(${finalRotation}deg);">
								<div class="val-row">${topContent}</div>
								<div class="val-row">${bottomContent}</div>
							</div>`,
						iconSize: [0, 0]
					});

					// Gebruik targetLayer als die beschikbaar is (voor split-screen), anders de standaard layer
					const destinationLayer = (typeof targetLayer !== 'undefined') ? targetLayer : layer;
					L.marker(midPos, { icon: labelIcon, interactive: false }).addTo(destinationLayer);
				}
			}
		}
	}
	
	// 5. Voorbereiden van data
	features.forEach(f => {
		const linkId = f.prop.id;
		const coords = f.geom.coor;
		let hasData = false; // Indicator om bij te houden of er intensiteiten zijn

		[1, 2].forEach(dir => {
            const sign = (dir === 1) ? -1 : 1;

            if (mode === 'een') {
                const val = data[linkId]?.[dir];
                if (val !== undefined) {
					hasData = true; // Data gevonden in modus 'een'
                    drawIntensityPolygon(linkId, coords, val, sign, f.prop, fullType, "none", 0);
                }
            } else {
                // VERGELIJKINGSMODUS
                const v1 = baseData[linkId]?.[dir] || 0; 
                const diff = data[linkId]?.[dir] || 0;

                // Bereken de breedte van de basis variant
                const widthV1 = (Math.abs(v1) / (maxLoad || 1)) * maxWidth;

                // 1. Teken Variant 1 (Grijs) altijd vanaf de as (offset 0)
                if (Math.abs(v1) > 0) {
					has_value = true
					drawIntensityPolygon(linkId, coords, v1, sign, f.prop, fullType, "basis", 0);
				}

                // 2. Teken het verschil (Rood of Groen)
                if (Math.abs(diff) > 0) {
					has_value = true
					drawIntensityPolygon(linkId, coords, diff, sign, f.prop, fullType, "diff", widthV1);
				}
				
				hasData = (baseData[linkId]?.[dir] > -1 || data[linkId]?.[dir] > -1)
				
            }
        });

		// Middelijn alleen tekenen als er daadwerkelijk intensiteiten zijn voor dit wegvak
		if (hasData) {

			// Middelijn tekenen
			const baseLine = coords.map(pt => crsRD.unproject(L.point(pt[0], pt[1])));
			const l = L.polyline(baseLine, { 
				color: 'black', 
				weight: 0.5, 
				opacity: 0.8, 
				interactive: false 
			}).addTo(layer);

			l.bringToFront(); // Zorgt dat de as altijd zichtbaar blijft bovenop de intensiteiten
		}
		
	});
    
	// 8. Boundary altijd als allerbovenste laag
	if (typeof boundarydraw !== 'undefined') {
		boundarydraw.bringToFront();
	}
	
	boundarydraw.bringToFront();
	
	let legendkrDiv = document.getElementById("legendkr");
	legendkrDiv.innerHTML = ``;

	const selectedVariantIndex = variants.indexOf(var1);
	const selectedVariantTweeIndex = variants.indexOf(var2);

	if (typeKey === 'o' && halteCheckbox) {

		haltes.forEach(([id, x, y, haltenaam]) => {

			const stappersinfo = stappers.find(([vIdx, idhalte]) => { return vIdx === selectedVariantIndex && idhalte === id; });
			stappersinfot = undefined;
			if (mode === "twee") { stappersinfot = stappers.find(([vIdxt, idhaltet]) => { return vIdxt === selectedVariantTweeIndex && idhaltet === id; }); }

			if (stappersinfo) {

				const [vIdx, idhalte, typee, fbos, fbas, fbet, laos, laas, laet, cbos, cbas, cbet, caos, caas, caet, wbos, wbas, wbet, waos, waas, waet] = stappersinfo;

        // Initialiseer de t variabelen vooraf als leeg/undefined voor als modus niet twee is
        let vIdxt, idhaltet, typeet, fbost, fbast, fbett, laost, laast, laett, cbost, cbast, cbett, caost, caast, caett, wbost, wbast, wbett, waost, waast, waett;

        if (mode === "twee" && stappersinfot) {
				
					[vIdxt, idhaltet, typeet, fbost, fbast, fbett, laost, laast, laett, cbost, cbast, cbett, caost, caast, caett, wbost, wbast, wbett, waost, waast, waett] = stappersinfot;

					const haltetype = getHalteTypeNaam(typeet);
					const latLng = crsRD.unproject(L.point(x, y));

					const circle = L.circle(latLng, {
						radius: 14,
						fillColor: getHalteColor(typeet),
						color: "#000",
						weight: 0.5,
						fillOpacity: 1,
						interactive: true
					}).addTo(layer);

					circle.on("click", () => {

						if (!stappersinfo) return;

						circle.bindPopup(`
							<h5><strong>Halte ${haltenaam} (${haltetype})</strong></h5>
							<table class="table table-sm table-striped table-borderless" style="text-align: center; vertical-align: middle; table-layout: fixed; width: 100%;">
								<thead>
									<tr>
										<td style="width: 270px;"><strong>${var2}</strong></td>
										<td style="width: 100px;"><strong>Ochtendspits<br>(7-9 uur)</strong></td>
										<td style="width: 100px;"><strong>Avondspits<br>(16-18 uur)</strong></td>
										<td style="width: 100px;"><strong>Etmaal<br>(0-24 uur)</strong></td>
									</tr>
								</thead>
								<tbody>
