			});
			
		} else {
		
			krstats.forEach(([vIdx, idkr, type, x, y]) => {
			
				// filter op geselecteerde variant
				if (vIdx !== selectedVariantTweeIndex) return;

				const latLng = crsRD.unproject(L.point(x, y));

				const gevonden = krstats.some(([vIdxx, idkrr]) => {
					return vIdxx === selectedVariantIndex && idkrr === idkr;
				});

				if (gevonden) {
				
					L.circle(latLng, {
						radius: 8,
						fillColor: getKruispuntColor(type),
						color: "#000",
						weight: 0.5,
						fillOpacity: 1,
						interactive: true
					}).on('click', () => {
							showKruispuntInfo(selectedVariantIndex, idkr, 2, selectedVariantTweeIndex);
					}).addTo(layer);
					
				} else {
				
					L.circle(latLng, {
						radius: 8,
						fillColor: getKruispuntColor(type),
						color: "#000",
						weight: 0.5,
						fillOpacity: 1,
						interactive: true
					}).on('click', () => {
							showKruispuntInfo(selectedVariantTweeIndex, idkr, 2, "");
					}).addTo(layer);
				
				}
				
			});
		
		}
		function getVriColor(value) {
			switch(value) {
				case 2: return "red";
				case 1: return "orange";
				case 0: return "green";
				default: return "gray";
			}
		}
		
		function createHalfCircle(latLng, radius, startAngle, endAngle) {

			const center = crsRD.project(latLng); // RD meters
			const points = [];
			const steps = 128;

			for (let i = 0; i <= steps; i++) {
				const angle = startAngle + (endAngle - startAngle) * (i / steps);

				const x = center.x + radius * Math.cos(angle);
				const y = center.y + radius * Math.sin(angle);

				points.push(crsRD.unproject(L.point(x, y)));
			}

			points.push(latLng);

			return points;
		}
		
		vristats.forEach(([vIdx, id, x, y, tag, vos, vas, wvos, wvas, cos, cas, tos, tas, bos, bas]) => {

			if (vIdx !== selectedVariantIndex) return;

			const latLng = crsRD.unproject(L.point(x, y));

			if (mode === "een" && timeKey === "et") {

				const leftColor = getVriColor(bos);
				const rightColor = getVriColor(bas);

				const radius = 14; // meters

				// linker helft (p/2 ? 3p/2)
				const leftHalf = createHalfCircle(latLng, radius, Math.PI/2, 3*Math.PI/2);

				// rechter helft (-p/2 ? p/2)
				const rightHalf = createHalfCircle(latLng, radius, -Math.PI/2, Math.PI/2);

				// tekenen
				L.polygon(leftHalf, {
					color: "#000",
					weight: 0.5,
					fillColor: leftColor,
					fillOpacity: 1,
					interactive: true
				}).on('click', () => {
					showKruispuntInfo(vIdx, id, 1, "");
				}).addTo(layer);

				L.polygon(rightHalf, {
					color: "#000",
					weight: 0.5,
					fillColor: rightColor,
					fillOpacity: 1,
					interactive: true
				}).on('click', () => {
					showKruispuntInfo(vIdx, id, 1, "");
				}).addTo(layer);
				
			} else if (mode === "een") {
			
				const value = (timeKey === "os") ? bos : bas;
				const color = getVriColor(value);

				L.circle(latLng, {
					radius: 14,
					fillColor: color,
					color: "#000",
					weight: 0.5,
					fillOpacity: 1,
					interactive: true
				}).on('click', () => {
					showKruispuntInfo(vIdx, id, 1, "");
				}).addTo(layer);
			
			} else {
			
				L.circle(latLng, {
					radius: 14,
					fillColor: "#800080",
					color: "#000",
					weight: 0.5,
					fillOpacity: 1,
					interactive: true
				}).on('click', () => {
					showKruispuntInfo(vIdx, id, 1, selectedVariantTweeIndex);
				}).addTo(layer);
			
			}
		});
		
	}	
	
}

