function renderKruispunt({takken, hoeken, pin, vin, canvasId}) {

	const kleuren = ["#E69F00","#56B4E9","#009E73","#F0E442","#0072B2","#D55E00","#CC79A7","#000000","#999999","#66C2A5"]

	const canvas = document.getElementById(canvasId);
	const ctx = canvas.getContext("2d");

	const cx = canvas.width / 2;
	const cy = canvas.height / 2;
	const radius = 150;
	const curve = 20;

	const tangentOffset = 20;
	const rechtLengte = 30;

	const factor = 2.5;

	const intensiteiten = pin.map((rij, i) => 
		rij.map((waardeA, j) => {
			const waardeB = vin[i][j];
			// Als een van de waarden -1 is, beschouwen we de hele turn als 'geen data'
			if (waardeA === -1 && waardeB === -1) return -1;
			if (waardeA === -1 && waardeB > -1) return waardeB * 2.5;
			if (waardeA > -1 && waardeB === -1) return waardeA;

			return waardeA + (waardeB * 2.5);
			
		})
	);

	// ===================
	// NIEUW: NORMALISATIE
	// ===================
	const minWidth = 2;
	const maxWidth = 20;
	const maxIntensiteit = Math.max(...intensiteiten.flat());

	function schaal(i) {
		if (i < 0) return 0;
		
		const norm = i / (maxIntensiteit); // Voorkom delen door nul
		const gamma = 0.6;
		const scaled = Math.pow(norm, gamma);

		return minWidth + scaled * (maxWidth - minWidth);
	}

	// =====================
	// GEOMETRIE
	// =====================
	const nodes = takken.map((t, i) => {
		const hoek = hoeken[i] * Math.PI / 180;

		const nx = Math.cos(hoek);
		const ny = Math.sin(hoek);

		const tx = Math.cos(hoek + Math.PI / 2);
		const ty = Math.sin(hoek + Math.PI / 2);

		const x = cx + radius * nx;
		const y = cy + radius * ny;

		return { x, y, nx, ny, tx, ty, hoek };
	});

	// =====================
	// SORTERING (ongewijzigd)
	// =====================
	function sorteerOutbound() {
		return nodes.map((nodeI, i) => {
			let doelen = [];
			nodes.forEach((nodeJ, j) => {
				if (i === j) return; // Alleen eigen tak overslaan, 0 intensiteit mag nu wel.

				let d = nodeJ.hoek - nodeI.hoek;
				if (d < 0) d += 2 * Math.PI;
				doelen.push({ j, hoek: d });
			});
			doelen.sort((a, b) => a.hoek - b.hoek);
			return doelen.map(d => d.j);
		});
	}

	function sorteerInbound() {
		return nodes.map((nodeJ, j) => {
			let herkomsten = [];

			nodes.forEach((nodeI, i) => {
				if (i === j) return;

				let d = nodeI.hoek - nodeJ.hoek;
				if (d < 0) d += 2 * Math.PI;

				herkomsten.push({ i, hoek: d });
			});

			herkomsten.sort((a, b) => a.hoek - b.hoek);
			return herkomsten.map(h => h.i).reverse();
		});
	}

	const outboundVolgorde = sorteerOutbound();
	const inboundVolgorde  = sorteerInbound();

	// =====================
	// OFFSETS
	// =====================
	function computeOffsets() {
		const offsetsOut = nodes.map(() => []);
		const offsetsIn  = nodes.map(() => []);

		outboundVolgorde.forEach((lijst, i) => {
			let offset = 0;
			lijst.forEach(j => {
				const w = schaal(intensiteiten[i][j]);
				offsetsOut[i][j] = offset + w / 2;
				offset += w;
			});
		});

		inboundVolgorde.forEach((lijst, j) => {
			let offset = 0;
			lijst.forEach(i => {
				const w = schaal(intensiteiten[i][j]);
				offsetsIn[j][i] = offset + w / 2;
				offset += w;
			});
		});

		return { offsetsOut, offsetsIn };
	}

	const { offsetsOut, offsetsIn } = computeOffsets();

	function bepaalInboundRange(j) {
		let min = Infinity;
		let max = -Infinity;

		inboundVolgorde[j].forEach(i => {
			const val = intensiteiten[i][j];
			if (val <= 0) return;

			const w = schaal(val);
			const offset = offsetsIn[j][i];

			const a = offset - w / 2 + 20;
			const b = offset + w / 2 + 20;

			if (a < min) min = a;
			if (b > max) max = b;
		});

		if (min === Infinity) return null;

		return { min, max };
	}

	function tekenInboundDriehoekHalf(n, range, hoogte) {
		if (!range) return;

		// ===== BASIS START (eerste inbound band) =====
		const startX = n.x + n.tx * range.min;
		const startY = n.y + n.ty * range.min;

		// ===== MIDDEN VAN DE RANGE =====
		const midOffset = (range.min + range.max) / 2;

		const midX = n.x + n.tx * midOffset;
		const midY = n.y + n.ty * midOffset;

		// ===== PUNT (naar binnen) =====
		const tipX = startX - n.nx * hoogte;
		const tipY = startY - n.ny * hoogte;

		// ===== TEKENEN =====
		ctx.beginPath();
		ctx.moveTo(startX, startY);  // begin inbound
		ctx.lineTo(midX, midY);      // midden
		ctx.lineTo(tipX, tipY);      // punt
		ctx.closePath();

		ctx.fillStyle = `white`;
		ctx.fill();
		
		
		ctx.strokeStyle = `white`;
		ctx.lineWidth = 6;
		ctx.stroke();
	}

	function tekenInboundDriehoekBuiten(n, range, hoogte) {
		if (!range) return;

		// ===== BASIS START (laatste inbound band = buitenzijde) =====
		const startX = n.x + n.tx * range.max;
		const startY = n.y + n.ty * range.max;

		// ===== MIDDEN =====
		const midOffset = (range.min + range.max) / 2;

		const midX = n.x + n.tx * midOffset;
		const midY = n.y + n.ty * midOffset;

		// ===== PUNT (naar buiten) =====
		const tipX = startX - n.nx * hoogte;
		const tipY = startY - n.ny * hoogte;

		// ===== TEKENEN =====
		ctx.beginPath();
		ctx.moveTo(startX, startY); // buitenste band
		ctx.lineTo(midX, midY);     // midden
		ctx.lineTo(tipX, tipY);     // punt naar buiten
		ctx.closePath();

		ctx.fillStyle = `white`;
		ctx.fill();
		
		ctx.strokeStyle = `white`;
		ctx.lineWidth = 6;
		ctx.stroke();
		
	}

	function bepaalOutboundRange(i) {
		let min = Infinity;
		let max = -Infinity;

		outboundVolgorde[i].forEach(j => {
			const val = intensiteiten[i][j];
			if (val <= 0) return;

			const w = schaal(val);
			const offset = offsetsOut[i][j];

			const a = offset - w / 2 + 20;
			const b = offset + w / 2 + 20;

			if (a < min) min = a;
			if (b > max) max = b;
		});

		if (min === Infinity) return null;

		return { min, max };
	}

	function tekenOutboundDriehoek(n, range, hoogte, kleur) {
		if (!range) return;

		// ===== BASIS =====
		const leftX  = n.x - n.tx * range.max;
		const leftY  = n.y - n.ty * range.max;

		const rightX = n.x - n.tx * range.min;
		const rightY = n.y - n.ty * range.min;

		// ===== MIDDEN =====
		const midOffset = (range.min + range.max) / 2;

		const midX = n.x - n.tx * midOffset;
		const midY = n.y - n.ty * midOffset;

		// ===== PUNT (180° gedraaid) =====
		const tipX = midX - n.nx * hoogte;
		const tipY = midY - n.ny * hoogte;

		// ===== TEKENEN =====
		ctx.beginPath();
		ctx.moveTo(leftX, leftY);
		ctx.lineTo(rightX, rightY);
		ctx.lineTo(tipX, tipY);
		ctx.closePath();

		ctx.fillStyle = kleur;
		ctx.fill();
		
		ctx.strokeStyle = `white`;
		ctx.lineWidth = 6;
		ctx.stroke();
	}


	// =====================
	// OD CURVES
	// =====================
function tekenOD() {

	const minAfstand = 50;   // minimale lengte voor curve
	const minHoek = 1;    // minimale hoek (radialen ~14°)

	nodes.forEach((ni, i) => {
		outboundVolgorde[i].forEach(j => {

			const val = intensiteiten[i][j];

			if (val === -1) return;

			const nj = nodes[j];
			const w = schaal(val);

			const oi = offsetsOut[i][j] + tangentOffset;
			const oj = offsetsIn[j][i] + tangentOffset;

			// ===== START / EINDE =====
			const sx = ni.x - ni.tx * oi;
			const sy = ni.y - ni.ty * oi;
			const ex = nj.x + nj.tx * oj;
			const ey = nj.y + nj.ty * oj;

			// ===== RECHTE STUKKEN =====
			const p1x = sx - ni.nx * rechtLengte;
			const p1y = sy - ni.ny * rechtLengte;
			const p2x = ex - nj.nx * rechtLengte;
			const p2y = ey - nj.ny * rechtLengte;

			// ===== HOEKVERSCHIL =====
			let diff = Math.abs(ni.hoek - nj.hoek);
			if (diff > Math.PI) diff = 2 * Math.PI - diff;

			// ===== AFSTAND =====
			const dx = ex - sx;
			const dy = ey - sy;
			const afstand = Math.sqrt(dx * dx + dy * dy);

			// ===== CONTROL POINTS (voor curve) =====
			const cpDist = 20 + (diff / Math.PI) * 100;
			const c1x = p1x - ni.nx * cpDist;
			const c1y = p1y - ni.ny * cpDist;
			const c2x = p2x - nj.nx * cpDist;
			const c2y = p2y - nj.ny * cpDist;

			// ===== PAD =====
			ctx.beginPath();
			ctx.moveTo(sx, sy);

			// eerste rechte stuk
			ctx.lineTo(p1x, p1y);

			if (afstand < minAfstand && diff < minHoek) {
				// ===== RECHTE VERBINDING =====
				ctx.lineTo(p2x, p2y);
			} else {
				// ===== BEZIER =====
				ctx.bezierCurveTo(c1x, c1y, c2x, c2y, p2x, p2y);
			}

			// tweede rechte stuk
			ctx.lineTo(ex, ey);

			// ===== BORDER =====
			ctx.strokeStyle = "rgba(0,0,0,1)";
			ctx.lineWidth = w;
			ctx.stroke();

			// ===== BAND =====
			ctx.strokeStyle = kleuren[i];
			ctx.lineWidth = w;
			ctx.stroke();
		});
	});

	// ===== INBOUND DRIEHOEKEN =====
	nodes.forEach((n, j) => {
		const range = bepaalInboundRange(j);
		if (!range) return;

		tekenInboundDriehoekHalf(n, range, 10);
		tekenInboundDriehoekBuiten(n, range, 10);
	});

	// ===== OUTBOUND DRIEHOEKEN =====
	nodes.forEach((n, i) => {
		const range = bepaalOutboundRange(i);
		if (!range) return;

		tekenOutboundDriehoek(
			n,
			range,
			10,
			`white`
		);
	});
}

	// =====================
	// LABELS & NAAMGEVING
	// =====================
	function tekenLabels() {
		ctx.save();
		ctx.font = "bold 9px Arial";
		ctx.fillStyle = "black";
		ctx.textBaseline = "middle";

		const lineHeight = 16; // vaste regelafstand (teksthoogte + padding)

		nodes.forEach((n, i) => {
			ctx.save();

			// ===== ROTATIE NAAR TAKRICHTING =====
			ctx.translate(n.x, n.y);

			let tekstHoek = n.hoek;

			let checkHoek = tekstHoek;
			while (checkHoek > Math.PI) checkHoek -= 2 * Math.PI;
			while (checkHoek < -Math.PI) checkHoek += 2 * Math.PI;

			if (Math.abs(checkHoek) > Math.PI / 2) {
				tekstHoek += Math.PI;
			}

			ctx.rotate(tekstHoek);

			// ===== TAKNAAM =====
			align = (Math.abs(checkHoek) > Math.PI / 2) ? "right" : "left" ;
			offsetq = (Math.abs(checkHoek) > Math.PI / 2) ? 45 : -45 ;
			ctx.textAlign = align;
			if (takken[i].toUpperCase() != "NM") { 
				ctx.fillText(takken[i].toUpperCase(), offsetq, 0);
			}

			// =====================================================
			// OUTBOUND LABELS (simpel stapelen)
			// =====================================================
			outboundVolgorde[i].filter(j => pin[i][j] !== -1).forEach((j, idx) => {
				const val = pin[i][j];
				vam = vin[i][j];
				if (val === -1) return;
				if (vam === -1) { vam = 0 };
				

				const y = -25 - idx * lineHeight; // boven de tak

				ctx.save();
				flip = (nodes[i].hoek > Math.PI / 2 && nodes[i].hoek < 3 * Math.PI / 2) ? -1 : 1;
				ctx.translate(flip * 18, flip * y);

				ctx.font = "13px Arial";
				ctx.textAlign = "center";
				ctx.fillText(val + " (" + vam + ")", 20 * flip, 0);

				ctx.restore();
			});

			// =====================================================
			// INBOUND LABELS (onder de tak)
			// =====================================================
			inboundVolgorde[i].filter(j => pin[j][i] !== -1).forEach((j, idx) => {
				const val = pin[j][i];
				vam = vin[j][i];
				if (val === -1) return;
				if (vam === -1) { vam = 0 };

				const y = 25 + idx * lineHeight; // onder de tak

				ctx.save();
				flip = (nodes[i].hoek > Math.PI / 2 && nodes[i].hoek < 3 * Math.PI / 2) ? -1 : 1;
				
				ctx.translate(flip * 18, flip * y);

				ctx.font = "13px Arial";
				ctx.textAlign = "center";
				ctx.fillText(val + " (" + vam + ")", 20 * flip, 0);

				ctx.restore();
			});

			ctx.restore();
		});

		ctx.restore();
	}

	// =====================
	// RENDER
	// =====================
	function render() {
		ctx.clearRect(0, 0, canvas.width, canvas.height);
		tekenOD();
		tekenLabels(); // De nieuwe functie
	}

	render();

}

