def clip_linestring_to_polygon(polygon, line)
  xs = polygon.map { |p| p[0] }
  ys = polygon.map { |p| p[1] }

  min_x, max_x = xs.min, xs.max
  min_y, max_y = ys.min, ys.max

  result = []
  current = []

  line.each_cons(2) do |(x1, y1), (x2, y2)|
    dx = x2 - x1
    dy = y2 - y1

    t0 = 0.0
    t1 = 1.0

    checks = [
      [-dx, x1 - min_x],
      [ dx, max_x - x1],
      [-dy, y1 - min_y],
      [ dy, max_y - y1]
    ]

    visible = true

    checks.each do |p, q|
      if p == 0
        if q < 0
          visible = false
          break
        end
      else
        t = q.to_f / p
        if p < 0
          t0 = [t0, t].max
        else
          t1 = [t1, t].min
        end
      end
    end

    if visible && t0 <= t1
      cx1 = x1 + t0 * dx
      cy1 = y1 + t0 * dy
      cx2 = x1 + t1 * dx
      cy2 = y1 + t1 * dy

      current << [cx1, cy1] if current.empty? || current.last != [cx1, cy1]
      current << [cx2, cy2]
    else
      unless current.empty?
        result << current
        current = []
      end
    end
  end

  result << current unless current.empty?
  result
end

def wkt_to_coords(wkt)
  return [] if wkt.nil? || wkt.strip.empty?
  m = wkt.match(/LINESTRING\((.+)\)/)
  return [] unless m
  m[1].split(',').map do |pt|
    x, y = pt.strip.split(' ')
    [x.to_f, y.to_f]
  end
end

def calculate_midpoint_info(points_rd)
  return { ml: 0, mx: 0, my: 0, ma: 0, mo: 0 } if points_rd.nil? || points_rd.empty?
  
  # 1. Bereken totale afstand
  total_dist = 0.0
  segs = (0...points_rd.length-1).map do |i|
    p1, p2 = points_rd[i], points_rd[i+1]
    d = Math.sqrt((p2[0]-p1[0])**2 + (p2[1]-p1[1])**2)
    total_dist += d
    {p1: p1, p2: p2, dx: (p2[0]-p1[0]).to_f, dy: (p2[1]-p1[1]).to_f, d: d}
  end

  # 2. Zoek het exacte midden
  half, acc = total_dist / 2.0, 0.0
  segs.each do |s|
    if acc + s[:d] >= half || s == segs.last
      r = s[:d] > 0 ? (half - acc) / s[:d] : 0
      
      # Midden op de lijn (RD coördinaten)
      mx, my = s[:p1][0] + (s[:dx] * r), s[:p1][1] + (s[:dy] * r)

      # Richting van het segment (dx, dy)
      # Normaliseer de richting (unit vector)
      len = Math.sqrt(s[:dx]**2 + s[:dy]**2)
      ux = s[:dx] / len
      uy = s[:dy] / len

      # De loodrechte vector (normaal) in RD:
      # Als de weg (ux, uy) is, dan is loodrecht rechts: (uy, -ux)
      # En loodrecht links: (-uy, ux)
      
      # Richting 1 en 2 van de weg
      m_yeen = my - ux
      m_ytwee = my + ux
      
      # Label omdraaien op kaart
      eerste = m_yeen < m_ytwee ? 1 : 2
      eerste = m_yeen == m_ytwee ? 0 : eerste

      # Hoek voor de tekst (in graden)
      # Math.atan2(dx, dy) geeft de hoek t.o.v. de Y-as (noorden)
      bearing = (Math.atan2(s[:dx], s[:dy]) * 180.0 / Math::PI + 360) % 360
      
      # Correctie voor tekstleesbaarheid (zodat tekst niet ondersteboven staat)
      text_angle = (bearing > 90 && bearing < 270) ? bearing - 180 : bearing
      # Omzetten naar de hoek die CSS/Leaflet verwacht (0 = horizontaal)
      final_angle = (text_angle - 90 + 360) % 360

      return { 
        ml: total_dist.round(0),
        mx: mx.round(2),
        my: my.round(2),
        ma: final_angle.round(2),
        mo: eerste.round(0)
      }
    end
    acc += s[:d]
  end
end

