        WHEN signaltype_ochtend = 2 AND vc_ochtend > 89 AND wvc_ochtend > 89 THEN 2
        WHEN signaltype_ochtend = 2 AND vc_ochtend >= 89 AND wvc_ochtend <= 89 AND cyclus_ochtend > 80 THEN 1
        WHEN signaltype_ochtend = 2 AND vc_ochtend >= 89 AND wvc_ochtend <= 89 AND cyclus_ochtend <= 80 THEN 0
        WHEN signaltype_ochtend = 2 AND vc_ochtend <= 89 AND wvc_ochtend <= 89 THEN 0
      ELSE NULL END AS bos,
      CASE
        WHEN signaltype_avond = 1 AND vc_avond > 89 AND wvc_avond > 89 THEN 2
        WHEN signaltype_avond = 1 AND vc_avond > 89 AND wvc_avond <= 89 AND cyclus_avond > 80 THEN 1
        WHEN signaltype_avond = 1 AND vc_avond > 89 AND wvc_avond <= 89 AND cyclus_avond <= 80 THEN 0
        WHEN signaltype_avond = 1 AND vc_avond <= 89 AND wvc_avond <= 89 THEN 0
        WHEN signaltype_avond = 2 AND vc_avond > 89 AND wvc_avond > 89 THEN 2
        WHEN signaltype_avond = 2 AND vc_avond >= 89 AND wvc_avond <= 89 AND cyclus_avond > 80 THEN 1
        WHEN signaltype_avond = 2 AND vc_avond >= 89 AND wvc_avond <= 89 AND cyclus_avond <= 80 THEN 0
        WHEN signaltype_avond = 2 AND vc_avond <= 89 AND wvc_avond <= 89 THEN 0
      ELSE NULL END AS bas
    FROM (
      SELECT
        v,
        nodenr,
        x,
        y,
        nodetag,
        MAX(CASE WHEN time = 1 THEN vc END) AS vc_ochtend,
        MAX(CASE WHEN time = 3 THEN vc END) AS vc_avond,
        MAX(CASE WHEN time = 1 THEN wvc END) AS wvc_ochtend,
        MAX(CASE WHEN time = 3 THEN wvc END) AS wvc_avond,
        MAX(CASE WHEN time = 1 THEN cyclus END) AS cyclus_ochtend,
        MAX(CASE WHEN time = 3 THEN cyclus END) AS cyclus_avond,
        MAX(CASE WHEN time = 1 THEN signaltype END) AS signaltype_ochtend,
        MAX(CASE WHEN time = 3 THEN signaltype END) AS signaltype_avond
      FROM (
        SELECT '" + variant + "' AS v, n11.nodenr, ROUND(p.x::numeric, 1) AS x, ROUND(p.y::numeric, 1) AS y, n12.nodetag, n51.time, ROUND(n51.vcratio*100)::INT AS vc, ROUND(n51.wvcratio*100)::INT AS wvc, ROUND(n51.calccycletime)::INT AS cyclus, n51.usedsignaltype AS signaltype
        FROM (SELECT pointnr, x, y FROM point WHERE pointtype = 2 AND x BETWEEN " + min_x + " AND " + max_x + " AND y BETWEEN " + min_y + " AND " + max_y + " GROUP BY pointnr, x, y) p
        INNER JOIN node1data1 AS n11 ON n11.nodenr = p.pointnr AND n11.junctiontype = 3
        LEFT JOIN node1data2 AS n12 ON n12.nodenr = p.pointnr
        LEFT JOIN node5data1 AS n51 ON n51.nodenr = p.pointnr AND n51.purpose = 10 AND n51.mode = 1 AND n51.time IN (1,3) AND n51.user IN (1000, 3000) AND n51.result = 5 AND n51.iteration = 20
      ) q
      GROUP BY v, nodenr, x, y, nodetag
    ) w"

    VriPointData.open 
    writeln "Aantal geregelde kruispunten in de polygon: " + VriPointData.recordCount.to_s
    while !VriPointData.eof?; vripointdata << VriPointData.get; VriPointData.next; end
    KrPointData.close

    unique_nodenr = (krpointdata + vripointdata).map { |row| row[1] }.compact.uniq

    KrIntData = OtQuery.new
    KrIntData.sql = "SELECT
      '#{variant}' AS v,
      n.nodenr AS n,
      nd.nodetag AS t,
      p.x,
      p.y,
      la.linenr AS a,
      lb.linenr AS b,
      na.name AS sa,
      nb.name AS sb,
      (ROUND(SUM(td.load) FILTER (WHERE td.mode IN (1,12) AND td.time = 1) / 10.0) * 10)::int AS pos,
      (ROUND(SUM(td.load) FILTER (WHERE td.mode IN (1,12) AND td.time = 3) / 10.0) * 10)::int AS pas,
      (ROUND(SUM(td.load) FILTER (WHERE td.mode IN (1,12) AND td.time IN (1,2,3)) / 10.0) * 10)::int AS pet,
      (ROUND(SUM(td.load) FILTER (WHERE td.mode = 9 AND td.time = 1) / 10.0) * 10)::int AS vos,
      (ROUND(SUM(td.load) FILTER (WHERE td.mode = 9 AND td.time = 3) / 10.0) * 10)::int AS vas,
      (ROUND(SUM(td.load) FILTER (WHERE td.mode = 9 AND td.time IN (1,2,3)) / 10.0) * 10)::int AS vet
    FROM triline tl
    JOIN node n ON n.nodenr = tl.pointnrb AND n.nodenr IN (#{unique_nodenr.join(",")})
    JOIN point p ON p.pointnr = n.nodenr
    LEFT JOIN node1data2 nd ON nd.nodenr = n.nodenr
    LEFT JOIN line la ON (tl.pointnra = la.pointnra AND tl.pointnrb = la.pointnrb) OR (tl.pointnrb = la.pointnra AND tl.pointnra = la.pointnrb)
    LEFT JOIN line lb ON (tl.pointnrc = lb.pointnra AND tl.pointnrb = lb.pointnrb) OR (tl.pointnrb = lb.pointnra AND tl.pointnrc = lb.pointnrb)
    JOIN link lka ON lka.linknr = la.linenr AND la.linetype = 1 
    JOIN link lkb ON lkb.linknr = lb.linenr AND lb.linetype = 1  
    LEFT JOIN name na ON la.namenr = na.namenr AND la.linetype = na.objecttype AND na.objecttype = 1 AND na.object = 2 AND la.linenr = lka.linknr AND la.linetype = 1
    LEFT JOIN name nb ON lb.namenr = nb.namenr AND lb.linetype = nb.objecttype AND nb.objecttype = 1 AND nb.object = 2 AND lb.linenr = lkb.linknr AND lb.linetype = 1
    JOIN turn5data1 td ON td.turnnr = tl.trilinenr AND td.purpose = 10 AND td.mode IN (1,9,12) AND td.time IN (1,2,3) AND td.\"user\" IN (1000,3000) AND td.result IN (4,5) AND td.iteration IN (1,20)
    WHERE tl.pointtypea = 2 AND tl.pointtypeb = 2 AND tl.pointtypec = 2
    GROUP BY n.nodenr, nd.nodetag, p.x, p.y, la.linenr, lb.linenr, na.name, nb.name"

    KrIntData.open 
    writeln "Aantal intensiteiten op kruispunten gevonden: " + KrIntData.recordCount.to_s
    while !KrIntData.eof?; krintensiteiten << KrIntData.get; KrIntData.next; end
    KrIntData.close 

    # Lines bij elkaar zoeken in boundary per variant
    StappersData = OtQuery.new
    StappersData.sql = "SELECT
        '" + variant + "' AS v, s.stopnr, s2d1.typenr,
        (ROUND(SUM(CASE WHEN s5d1.time = 1 THEN firstboarding ELSE 0 END) / 100.0) * 100)::integer AS firstboarding_os,
        (ROUND(SUM(CASE WHEN s5d1.time = 3 THEN firstboarding ELSE 0 END) / 100.0) * 100)::integer AS firstboarding_as,
        (ROUND(SUM(CASE WHEN s5d1.time IN (1,2,3) THEN firstboarding ELSE 0 END) / 100.0) * 100)::integer AS firstboarding_et,
        (ROUND(SUM(CASE WHEN s5d1.time = 1 THEN lastalighting ELSE 0 END) / 100.0) * 100)::integer AS lastalighting_os,
        (ROUND(SUM(CASE WHEN s5d1.time = 3 THEN lastalighting ELSE 0 END) / 100.0) * 100)::integer AS lastalighting_as,
        (ROUND(SUM(CASE WHEN s5d1.time IN (1,2,3) THEN lastalighting ELSE 0 END) / 100.0) * 100)::integer AS lastalighting_et,
        (ROUND(SUM(CASE WHEN s5d1.time = 1 THEN changeboarding ELSE 0 END) / 100.0) * 100)::integer AS changeboarding_os,
        (ROUND(SUM(CASE WHEN s5d1.time = 3 THEN changeboarding ELSE 0 END) / 100.0) * 100)::integer AS changeboarding_as,
        (ROUND(SUM(CASE WHEN s5d1.time IN (1,2,3) THEN changeboarding ELSE 0 END) / 100.0) * 100)::integer AS changeboarding_et,
        (ROUND(SUM(CASE WHEN s5d1.time = 1 THEN changealighting ELSE 0 END) / 100.0) * 100)::integer AS changealighting_os,
        (ROUND(SUM(CASE WHEN s5d1.time = 3 THEN changealighting ELSE 0 END) / 100.0) * 100)::integer AS changealighting_as,
        (ROUND(SUM(CASE WHEN s5d1.time IN (1,2,3) THEN changealighting ELSE 0 END) / 100.0) * 100)::integer AS changealighting_et,
        (ROUND(SUM(CASE WHEN s5d1.time = 1 THEN walkboarding ELSE 0 END) / 100.0) * 100)::integer AS walkboarding_os,
        (ROUND(SUM(CASE WHEN s5d1.time = 3 THEN walkboarding ELSE 0 END) / 100.0) * 100)::integer AS walkboarding_as,
        (ROUND(SUM(CASE WHEN s5d1.time IN (1,2,3) THEN walkboarding ELSE 0 END) / 100.0) * 100)::integer AS walkboarding_et,
        (ROUND(SUM(CASE WHEN s5d1.time = 1 THEN walkalighting ELSE 0 END) / 100.0) * 100)::integer AS walkalighting_os,
        (ROUND(SUM(CASE WHEN s5d1.time = 3 THEN walkalighting ELSE 0 END) / 100.0) * 100)::integer AS walkalighting_as,
        (ROUND(SUM(CASE WHEN s5d1.time IN (1,2,3) THEN walkalighting ELSE 0 END) / 100.0) * 100)::integer AS walkalighting_et
    FROM point p
    JOIN stop s ON p.pointnr = s.stopnr
    JOIN name n ON p.namenr = n.namenr AND p.pointtype = n.objecttype AND n.objecttype = 5 AND n.object = 1
    JOIN stop5_4data1 s5d1 ON s5d1.stopnr = p.pointnr AND s5d1.purpose = 10 AND s5d1.user IN (1000,3000) AND s5d1.result BETWEEN 315 AND 377
    LEFT JOIN stop2data1 s2d1 ON s2d1.stopnr = p.pointnr AND s2d1.serienr = 17 AND s2d1.typenr > 0
    WHERE p.pointtype = 5 and p.x BETWEEN " + min_x + " AND " + max_x + " AND p.y BETWEEN " + min_y + " AND " + max_y + "
      AND NOT EXISTS (
        SELECT 1
        FROM centroid c
        JOIN point p2
            ON p2.pointnr = c.centroidnr
           AND p2.pointtype = 1
        WHERE ROUND(p2.x::numeric, 0) = ROUND(p.x::numeric, 0) AND ROUND(p2.y::numeric, 0) = ROUND(p.y::numeric, 0)
      )
    GROUP BY s.stopnr, p.x, p.y, s2d1.typenr"
    StappersData.open
    while !StappersData.eof?; stappers << StappersData.get; StappersData.next; end
    writeln "Aantal haltes met in-, uit- of overstappers gevonden: " + StappersData.recordCount.to_s
    StappersData.close
    stappers = []

  end

  krint_export = []

  # Loop door elke unieke node die gevonden is in de selectie
  unique_nodenr.each do |nodenr|
    varianten.each_with_index do |v_naam, v_idx|
      
      #  && (!row[9].nil? || !row[10].nil? || !row[11].nil? || !row[12].nil?  || !row[13].nil?  || !row[14].nil?)
      turns = krintensiteiten.select { |row| row[0] == v_naam && row[1] == nodenr }
      next if turns.empty?

      # Identificeer alle unieke links die verbonden zijn aan dit kruispunt (zowel in als uit)[cite: 1]
      connected_links = turns.map { |t| [t[5], t[6]] }.flatten.compact.uniq
      
      # Sorteer links op hoek ten opzichte van de node voor een logische matrix volgorde
      links_met_hoek = connected_links.map do |line_id|
        line_geom = linesall[line_id]
        hoek = -2
        straatnaam = "Nm" # Fallback

        # Gebruik numerieke indexen omdat 'turns' een Array van Arrays is
        matching_row = turns.find { |t| t[5] == line_id || t[6] == line_id }

        if matching_row
          # Pak kolom 7 (sa) als line_id in kolom 5 (a) staat, anders kolom 8 (sb)
          straatnaam = (matching_row[5] == line_id) ? matching_row[7] : matching_row[8]
        else
          # Fallback voor als de link niet direct in de turns-tabel staat
          straatnaam = "Link #{line_id}"
        end

        # Zorg dat de straatnaam nooit nil is (bijv. door NULL in database)
        straatnaam ||= "Nm"

        if line_geom
          coords = line_geom[:geom][:coor]
          p_node = [turns.first[3], turns.first[4]] # x, y van de node
          p_adj = (coords.first == p_node) ? coords[1] : coords[-2]
          if p_adj
            dx = p_adj[0] - p_node[0]
            dy = p_adj[1] - p_node[1]
            hoek = ((Math.atan2(dx, dy) * 180.0 / Math::PI + 360) % 360).to_i
          end
        end
        { id: line_id, hoek: hoek, naam: straatnaam }
      end.sort_by { |l| l[:hoek] }

      # Geordende lijsten voor de matrix assen
      sorted_ids = links_met_hoek.map { |l| l[:id] }
      sorted_hoeken = links_met_hoek.map { |l| l[:hoek].to_i }
      sorted_namen = links_met_hoek.map { |l| l[:naam] || "Nm" }

      # Zoek indices met ongeldige hoek, oftewel troep in de database
      remove_indices = sorted_hoeken.each_index.select { |i| sorted_hoeken[i] == -2 }

      # Verwijder uit assenlijsten (achterstevoren ivm indexverschuiving)
      remove_indices.reverse_each do |idx|
        sorted_ids.delete_at(idx)
        sorted_hoeken.delete_at(idx)
        sorted_namen.delete_at(idx)
      end

      # Initialiseer matrices (rij = herkomst link, kolom = bestemming link)
      # De structuur wordt [herkomst_idx][bestemming_idx]
      matrix_size = sorted_ids.size
      hb_pos = Array.new(matrix_size) { Array.new(matrix_size, -1) }
      hb_pas = Array.new(matrix_size) { Array.new(matrix_size, -1) }
      hb_pet = Array.new(matrix_size) { Array.new(matrix_size, -1) }
      hb_vos = Array.new(matrix_size) { Array.new(matrix_size, -1) }
      hb_vas = Array.new(matrix_size) { Array.new(matrix_size, -1) }
      hb_vet = Array.new(matrix_size) { Array.new(matrix_size, -1) }

      # Vul de matrices op basis van de turn data[cite: 1]
      turns.each do |t|
        h_idx = sorted_ids.index(t[5]) # Index van inkomende link a[cite: 1]
        b_idx = sorted_ids.index(t[6]) # Index van uitgaande link b[cite: 1]
        
        if h_idx && b_idx
          hb_pos[h_idx][b_idx] = t[9] || -1 # pos[cite: 1]
          hb_pas[h_idx][b_idx] = t[10] || -1 # pas[cite: 1]
          hb_pet[h_idx][b_idx] = t[11] || -1 # pet[cite: 1]
          hb_vos[h_idx][b_idx] = t[12] || -1 # vos[cite: 1]
          hb_vas[h_idx][b_idx] = t[13] || -1 # vas[cite: 1]
          hb_vet[h_idx][b_idx] = t[14] || -1 # vet[cite: 1]
        end
      end

      krint_export << [v_idx, nodenr, sorted_namen, sorted_hoeken, sorted_ids, hb_pos, hb_pas, hb_pet, hb_vos, hb_vas, hb_vet]
      
    end
  end

  type_map = ["pos", "pas", "pet", "oos", "oas", "oet", "fos", "fas", "fet"]
  type_krin = ["pos", "pas", "pet", "vos", "vas", "vet"]
  
  wegvak_stats = wvintensiteiten.map do |r|
    [varianten.index(r[0]), type_map.index(r[1]), r[2], r[3], r[4]]
  end.select do |row|
    row.all? { |element| !element.nil? }
  end
  
  vri_stats = vripointdata.map do |r|
    [varianten.index(r[0]), r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9], r[10], r[11], r[12], r[13], r[14]]
  end 

  kr_stats = krpointdata.map do |r|
    [varianten.index(r[0]), r[1], r[2], r[3], r[4]]
  end

  halte_export = haltes.map do |r|
    [r[0], r[1], r[2], r[3]]
  end

  stappers_export = stappers.map do |r|
    [varianten.index(r[0]), r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9], r[10], r[11], r[12], r[13], r[14], r[15], r[16], r[17], r[18], r[19], r[20]]
  end

  final_data = {
    meta: { prj: vma_projectnummer, nam: vma_projectnaam, vma: vma_versie, dat: Time.now.strftime("%d-%m-%Y"), maps: { vars: varianten, types: type_map, inttypes: type_krin } },
    boundary: {
      type: "Feature",
      geometry: { type: "Polygon", coordinates: polygon_rd }
    },
    geo: { type: "FeatureCollection", features: lines.values },
    stats: wegvak_stats,
    vristats: vri_stats,
    krstats: kr_stats,
    krint: krint_export,
    haltes: halte_export,
    stappers: stappers_export
  }

  dynamische_content = "const trafficData = #{JSON.generate(final_data)};"
  volledig = before + dynamische_content + after
  resultaat = volledig.force_encoding("Windows-1252").encode("UTF-8")
  datum = Date.today.strftime("%Y-%m-%d")

  ruwe_naam = "#{vma_projectnummer}_#{datum}_#{vma_projectnaam}.html"
  bestandsnaam = ruwe_naam.gsub(' ', '-').downcase

  File.open(bestandsnaam, "w:UTF-8") do |f|
    f.write(resultaat)
  end
  
  writeln "Klaar! Het bestand '#{bestandsnaam}' is opgeslagen in de variant die geselecteerd stond."

else
  writeln "Geen areas gevonden om randen van de view te maken..."
end

ViewData.close